const u=Object.freeze({RARE:500,EPIC:1e3,LEGENDARY:5e3,MYTHIC:1e4});export function shopImpactXrdEquivalent(t){return u[t]||0}export function applySellDebuff({velocity:t,currentStrength:r,currentUntil:a,now:e,impactStrength:c,velocityPct:h,durationMs:i,maxDurationMs:o}){const n=Math.min(1,c/3);return{velocity:t*(1-h/100*n),strength:Math.max(r,n),until:Math.min(Math.max(a,e)+i,e+o)}}
